import type { Rule } from './types';

/**
 * The rules this tool ships with: 313 of them, from three sources.
 *
 * APPLICATION FIT — every threshold printed on a Axim or Corvus datasheet or
 * product page, each rule naming the document and the line it came from. Nothing
 * is inferred, because the one time a product fact went into a rule from memory on
 * this project it was wrong. Every technology has some; TTO, TIJ and VIJ took
 * theirs from the captured product pages rather than a PDF, which is where they
 * were all along.
 *
 * STRUCTURE — what makes a quote complete, and what makes it redundant. A printer
 * with nothing to mount it on, or five alternatives to one bracket. No datasheet
 * states these, so they cite data/quote-completeness.md, which says where the
 * judgement came from. None of them block.
 *
 * NARROWING — what the application rules out before anything is graded, exported
 * below as NARROWING_RULES. These used to be two comparisons in the API with no
 * rule code and no citation, which was the one place a product decision was made
 * outside the rule set.
 *
 * By technology: CIJ 79, LSR 28, PALM 98, PIJ 26, TIJ 22, TTO 28, VIJ 26, all 6
 *
 * Every sourceRef resolves to a file in this repository, and the generator fails
 * if one does not — a citation nobody can follow is decoration.
 *
 * Editable sources: data/application-rules.json, data/structure-rules.json,
 * data/narrowing-rules.json. Generated by data/build_rules.py. Do not hand-edit.
 */
