    technologyCode: "PALM",
    ruleType: "applicationFit",
    severity: "info",
    summary: "The published apply rate depends on the product spacing.",
    detail: "The sheet states the rate and then states what it depends on, in the same row: 'Single Apply: Up to 52 PPM; Dual Apply: Up to 28 PPM' followed by 'Dependent on Label Length, Print Speed and Product Spacing'. So 52 a minute is a ceiling under conditions, not a number to quote against a line whose spacing nobody has checked.\n\nNo minimum spacing is published anywhere, which is why this states the dependency instead of grading it. Writing a threshold here would mean inventing one. It fires only when the rep has answered the spacing question and is asking for more than the dual-apply figure — the point at which the three variables start trading against each other.",
