    detail: "Matched by word rather than by substring, so 'black ink' means Black and Black Thermo and does not mean Sky Blue. 'Grey' and 'gray' are one colour spelt two ways and asking for one never denies the other. Machines are narrowed on the Color attribute because a Corvus part number is the machine already filled; no machine is denied on a word in its description, because a machine can be refilled.",
